/**
 * A small, dependency-free QR Code encoder (ISO/IEC 18004): byte mode, error
 * correction level M, versions 1–40, automatic mask choice. Also a reader that
 * decodes a matrix back to text, so callers can prove nothing was truncated.
 */

/** Error-correction codewords per block and number of blocks at level M, indexed by version. */
const EC_PER_BLOCK = [0, 10, 16, 26, 18, 24, 16, 18, 22, 22, 26, 30, 22, 22, 24, 24, 28, 28, 26, 26, 26, 26, 28, 28, 28, 28, 28, 28, 28, 28, 28, 28, 28, 28, 28, 28, 28, 28, 28, 28, 28]
const BLOCKS = [0, 1, 1, 1, 2, 2, 4, 4, 4, 5, 5, 5, 8, 9, 9, 10, 10, 11, 13, 14, 16, 17, 17, 18, 20, 21, 23, 25, 26, 28, 29, 31, 33, 35, 37, 38, 40, 43, 45, 47, 49]
/** Level M in the format information is 0b00. */
const ECL_BITS = 0

export interface QrCode {
  version: number
  /** Modules per side (21 for version 1). */
  size: number
  /** 0–7. */
  mask: number
  /** `modules[y][x]` is true for a dark module. */
  modules: boolean[][]
}

/** Codeword-capable modules once function patterns are removed. */
function rawModules(version: number) {
  let result = (16 * version + 128) * version + 64
  if (version >= 2) {
    const align = Math.floor(version / 7) + 2
    result -= (25 * align - 10) * align - 55
    if (version >= 7) result -= 36
  }
  return result
}

const dataCodewords = (version: number) => Math.floor(rawModules(version) / 8) - EC_PER_BLOCK[version] * BLOCKS[version]

/** Largest UTF-8 payload in bytes that fits at level M for a version. */
export const byteCapacity = (version: number) => dataCodewords(version) - (version < 10 ? 2 : 3)

function alignmentPositions(version: number) {
  if (version === 1) return []
  const count = Math.floor(version / 7) + 2
  const step = version === 32 ? 26 : Math.ceil((version * 4 + 4) / (count * 2 - 2)) * 2
  const result = [6]
  for (let pos = version * 4 + 10; result.length < count; pos -= step) result.splice(1, 0, pos)
  return result
}

/* Reed–Solomon over GF(256) with the 0x11D polynomial. */
function multiply(x: number, y: number) {
  let z = 0
  for (let i = 7; i >= 0; i--) {
    z = (z << 1) ^ ((z >>> 7) * 0x11d)
    z ^= ((y >>> i) & 1) * x
  }
  return z
}

function rsDivisor(degree: number) {
  const result = Array<number>(degree).fill(0)
  result[degree - 1] = 1
  let root = 1
  for (let i = 0; i < degree; i++) {
    for (let j = 0; j < degree; j++) {
      result[j] = multiply(result[j], root)
      if (j + 1 < degree) result[j] ^= result[j + 1]
    }
    root = multiply(root, 2)
  }
  return result
}

function rsRemainder(data: number[], divisor: number[]) {
  const result = divisor.map(() => 0)
  for (const byte of data) {
    const factor = byte ^ (result.shift() as number)
    result.push(0)
    divisor.forEach((coef, i) => (result[i] ^= multiply(coef, factor)))
  }
  return result
}

/** Splits data into blocks (short blocks first) and returns each with its EC bytes. */
function blockLayout(version: number) {
  const count = BLOCKS[version]
  const ec = EC_PER_BLOCK[version]
  const raw = Math.floor(rawModules(version) / 8)
  const shortBlocks = count - (raw % count)
  const shortLen = Math.floor(raw / count) - ec
  return Array.from({ length: count }, (_, i) => shortLen + (i < shortBlocks ? 0 : 1))
}

const BCH = (data: number, poly: number, bits: number) => {
  let rem = data
  for (let i = 0; i < bits; i++) rem = (rem << 1) ^ ((rem >>> (bits - 1)) * poly)
  return (data << bits) | rem
}

const MASKS: ((x: number, y: number) => boolean)[] = [
  (x, y) => (x + y) % 2 === 0,
  (_, y) => y % 2 === 0,
  (x) => x % 3 === 0,
  (x, y) => (x + y) % 3 === 0,
  (x, y) => (Math.floor(x / 3) + Math.floor(y / 2)) % 2 === 0,
  (x, y) => ((x * y) % 2) + ((x * y) % 3) === 0,
  (x, y) => (((x * y) % 2) + ((x * y) % 3)) % 2 === 0,
  (x, y) => (((x + y) % 2) + ((x * y) % 3)) % 2 === 0,
]

/** Draws finders, timing, alignment and version info; returns the grid and which cells are reserved. */
function functionPatterns(version: number) {
  const size = version * 4 + 17
  const grid = Array.from({ length: size }, () => Array<boolean>(size).fill(false))
  const reserved = Array.from({ length: size }, () => Array<boolean>(size).fill(false))
  const set = (x: number, y: number, dark: boolean) => {
    grid[y][x] = dark
    reserved[y][x] = true
  }
  for (let i = 0; i < size; i++) {
    set(6, i, i % 2 === 0)
    set(i, 6, i % 2 === 0)
  }
  for (const [cx, cy] of [[3, 3], [size - 4, 3], [3, size - 4]]) {
    for (let dy = -4; dy <= 4; dy++)
      for (let dx = -4; dx <= 4; dx++) {
        const x = cx + dx
        const y = cy + dy
        const d = Math.max(Math.abs(dx), Math.abs(dy))
        if (x >= 0 && x < size && y >= 0 && y < size) set(x, y, d !== 2 && d !== 4)
      }
  }
  const align = alignmentPositions(version)
  align.forEach((ay, i) =>
    align.forEach((ax, j) => {
      const corner = (i === 0 && j === 0) || (i === 0 && j === align.length - 1) || (i === align.length - 1 && j === 0)
      if (corner) return
      for (let dy = -2; dy <= 2; dy++) for (let dx = -2; dx <= 2; dx++) set(ax + dx, ay + dy, Math.max(Math.abs(dx), Math.abs(dy)) !== 1)
    }),
  )
  // Format areas are reserved now and written once the mask is known.
  for (let i = 0; i < 9; i++) {
    if (i !== 6) set(8, i, false)
    if (i !== 6) set(i, 8, false)
  }
  for (let i = 0; i < 8; i++) {
    set(size - 1 - i, 8, false)
    set(8, size - 1 - i, false)
  }
  set(8, size - 8, true)
  if (version >= 7) {
    const bits = BCH(version, 0x1f25, 12)
    for (let i = 0; i < 18; i++) {
      const dark = ((bits >>> i) & 1) === 1
      const a = size - 11 + (i % 3)
      const b = Math.floor(i / 3)
      set(a, b, dark)
      set(b, a, dark)
    }
  }
  return { size, grid, reserved }
}

/** The 15 format-information cells in reading order for both copies. */
function formatCells(size: number) {
  const first: [number, number][] = []
  const second: [number, number][] = []
  for (let i = 0; i <= 5; i++) first.push([8, i])
  first.push([8, 7], [8, 8], [7, 8])
  for (let i = 9; i < 15; i++) first.push([14 - i, 8])
  for (let i = 0; i < 8; i++) second.push([size - 1 - i, 8])
  for (let i = 8; i < 15; i++) second.push([8, size - 15 + i])
  return { first, second }
}

/** Data cells in the standard zigzag order (two columns at a time, bottom-right first). */
function dataCells(size: number, reserved: boolean[][]) {
  const cells: [number, number][] = []
  for (let right = size - 1; right >= 1; right -= 2) {
    if (right === 6) right = 5
    for (let v = 0; v < size; v++) {
      for (let j = 0; j < 2; j++) {
        const x = right - j
        const upward = ((right + 1) & 2) === 0
        const y = upward ? size - 1 - v : v
        if (!reserved[y][x]) cells.push([x, y])
      }
    }
  }
  return cells
}

function penalty(m: boolean[][]) {
  const size = m.length
  let score = 0
  const lines = [...m, ...m[0].map((_, x) => m.map((row) => row[x]))]
  for (const line of lines) {
    let run = 1
    for (let i = 1; i <= size; i++) {
      if (i < size && line[i] === line[i - 1]) run++
      else {
        if (run >= 5) score += run - 2
        run = 1
      }
    }
    const s = line.map((d) => (d ? "1" : "0")).join("")
    score += 40 * ((s.match(/(?=10111010000|00001011101)/g) ?? []).length)
  }
  for (let y = 0; y < size - 1; y++)
    for (let x = 0; x < size - 1; x++) {
      const c = m[y][x]
      if (c === m[y][x + 1] && c === m[y + 1][x] && c === m[y + 1][x + 1]) score += 3
    }
  const dark = m.flat().filter(Boolean).length
  score += Math.floor(Math.abs(dark * 20 - size * size * 10) / (size * size)) * 10
  return score
}

/** Encodes `text` as UTF-8 bytes. Throws when it is longer than a version-40 code holds. */
export function encodeQr(text: string): QrCode {
  const bytes = Array.from(new TextEncoder().encode(text))
  let version = 1
  while (version <= 40 && bytes.length > byteCapacity(version)) version++
  if (version > 40) throw new RangeError(`Too long for a QR code: ${bytes.length} bytes (max ${byteCapacity(40)}).`)

  const capacity = dataCodewords(version) * 8
  const bits: number[] = []
  const push = (value: number, length: number) => {
    for (let i = length - 1; i >= 0; i--) bits.push((value >>> i) & 1)
  }
  push(0b0100, 4)
  push(bytes.length, version < 10 ? 8 : 16)
  bytes.forEach((b) => push(b, 8))
  push(0, Math.min(4, capacity - bits.length))
  push(0, (8 - (bits.length % 8)) % 8)
  for (let pad = 0xec; bits.length < capacity; pad ^= 0xec ^ 0x11) push(pad, 8)
  const data = Array.from({ length: bits.length / 8 }, (_, i) => bits.slice(i * 8, i * 8 + 8).reduce((a, b) => (a << 1) | b, 0))

  const divisor = rsDivisor(EC_PER_BLOCK[version])
  let offset = 0
  const blocks = blockLayout(version).map((len) => {
    const chunk = data.slice(offset, (offset += len))
    return { data: chunk, ec: rsRemainder(chunk, divisor) }
  })
  const codewords: number[] = []
  const longest = Math.max(...blocks.map((b) => b.data.length))
  for (let i = 0; i < longest; i++) blocks.forEach((b) => i < b.data.length && codewords.push(b.data[i]))
  for (let i = 0; i < divisor.length; i++) blocks.forEach((b) => codewords.push(b.ec[i]))

  const { size, grid, reserved } = functionPatterns(version)
  const cells = dataCells(size, reserved)
  const base = grid.map((row) => [...row])
  cells.forEach(([x, y], i) => (base[y][x] = i < codewords.length * 8 && ((codewords[i >>> 3] >>> (7 - (i & 7))) & 1) === 1))

  let best: QrCode | null = null
  let bestScore = Infinity
  MASKS.forEach((fn, mask) => {
    const modules = base.map((row) => [...row])
    cells.forEach(([x, y]) => fn(x, y) && (modules[y][x] = !modules[y][x]))
    const format = BCH((ECL_BITS << 3) | mask, 0x537, 10) ^ 0x5412
    const { first, second } = formatCells(size)
    first.forEach(([x, y], i) => (modules[y][x] = ((format >>> i) & 1) === 1))
    second.forEach(([x, y], i) => (modules[y][x] = ((format >>> i) & 1) === 1))
    const score = penalty(modules)
    if (score < bestScore) [best, bestScore] = [{ version, size, mask, modules }, score]
  })
  return best as unknown as QrCode
}

/**
 * Reads a matrix produced by `encodeQr` back to text and checks every block's
 * error-correction bytes. Returns null when anything doesn't add up.
 */
export function decodeQr(modules: boolean[][]): string | null {
  const size = modules.length
  const version = (size - 17) / 4
  if (!Number.isInteger(version) || version < 1 || version > 40) return null
  const { first } = formatCells(size)
  const format = first.reduce((acc, [x, y], i) => acc | ((modules[y][x] ? 1 : 0) << i), 0) ^ 0x5412
  const mask = (format >>> 10) & 7
  if ((format >>> 13) !== ECL_BITS || BCH(format >>> 10, 0x537, 10) !== format) return null

  const { reserved } = functionPatterns(version)
  const cells = dataCells(size, reserved)
  const total = Math.floor(rawModules(version) / 8)
  const codewords = Array.from({ length: total }, (_, i) =>
    cells.slice(i * 8, i * 8 + 8).reduce((acc, [x, y]) => (acc << 1) | (modules[y][x] !== MASKS[mask](x, y) ? 1 : 0), 0),
  )

  const lengths = blockLayout(version)
  const ecLen = EC_PER_BLOCK[version]
  const blocks = lengths.map(() => ({ data: [] as number[], ec: [] as number[] }))
  let k = 0
  for (let i = 0; i < Math.max(...lengths); i++) lengths.forEach((len, b) => i < len && blocks[b].data.push(codewords[k++]))
  for (let i = 0; i < ecLen; i++) blocks.forEach((b) => b.ec.push(codewords[k++]))
  const divisor = rsDivisor(ecLen)
  if (blocks.some((b) => rsRemainder(b.data, divisor).some((v, i) => v !== b.ec[i]))) return null

  const data = blocks.flatMap((b) => b.data)
  const bits = data.flatMap((byte) => Array.from({ length: 8 }, (_, i) => (byte >>> (7 - i)) & 1))
  let pos = 0
  const read = (n: number) => bits.slice(pos, (pos += n)).reduce((a, b) => (a << 1) | b, 0)
  if (read(4) !== 0b0100) return null
  const length = read(version < 10 ? 8 : 16)
  if (pos + length * 8 > bits.length) return null
  const bytes = Uint8Array.from({ length }, () => read(8))
  try {
    return new TextDecoder("utf-8", { fatal: true }).decode(bytes)
  } catch {
    return null
  }
}

"use client"

import * as React from "react"
import { CircleCheck, OctagonAlert, TriangleAlert } from "lucide-react"

import { cn } from "@/lib/utils"
import { byteCapacity, decodeQr, encodeQr, type QrCode } from "./qr-encode"

export { byteCapacity, decodeQr, encodeQr, type QrCode } from "./qr-encode"

export interface QrIssue {
  id: "hidden" | "local" | "staging" | "http" | "dense" | "too-long"
  tone: "warning" | "danger"
  message: string
  /** One-tap fix: the corrected URL and the button label. */
  fix?: { label: string; value: string }
}

const LOCAL = /^(localhost|127\.\d+\.\d+\.\d+|0\.0\.0\.0|\[::1\]|10\.\d+\.\d+\.\d+|192\.168\.\d+\.\d+|172\.(1[6-9]|2\d|3[01])\.\d+\.\d+)$|\.(local|localhost|internal|lan|home\.arpa)$/i
const STAGING = /(^|[.-])(staging|stage|stg|dev|preview|uat|qa|test|sandbox)([.-]|\d|$)|-git-|deploy-preview-/i
const TRACKING = /^(utm_\w+|fbclid|gclid|dclid|msclkid|mc_eid|igshid|ttclid|yclid)$/i
const HIDDEN = /[\s\u00a0\u200b-\u200f\u2028\u2029\u2060\ufeff]/g

/** Default issue messages; `{host}` and `{modules}` are filled in. Override any of them via `messages`. */
export const QR_MESSAGES = {
  hidden: "The link contains hidden spaces or invisible characters, so the code won't open what you see.",
  hiddenFix: "Remove them",
  local: "{host} only exists on your computer or network. A phone that scans this gets an error.",
  staging: "{host} looks like a staging site, not the live one.",
  publicFix: "Use {host}",
  http: "It opens over plain http, so phones may warn and the page can be tampered with.",
  httpFix: "Use https",
  dense: "Long link, dense code ({modules} dots): it needs printing large and scans slowly.",
  denseFix: "Remove tracking ({modules})",
  tooLong: "This link is too long to fit in a QR code at all.",
}

const fill = (template: string, values: Record<string, string>) =>
  template.replace(/\{(\w+)\}/g, (match, key: string) => values[key] ?? match)

const versionFor = (text: string) => {
  const bytes = new TextEncoder().encode(text).length
  for (let v = 1; v <= 40; v++) if (bytes <= byteCapacity(v)) return v
  return null
}

/** The URL with tracking parameters (utm_*, fbclid, gclid…) removed. */
export function withoutTracking(url: string) {
  try {
    const parsed = new URL(url)
    for (const key of [...parsed.searchParams.keys()]) if (TRACKING.test(key)) parsed.searchParams.delete(key)
    return parsed.toString()
  } catch {
    return url
  }
}

/**
 * What would go wrong if this URL were printed as a QR code: hidden characters,
 * hosts a phone can't reach, staging, plain http, and codes too dense to scan.
 */
export function checkQrUrl(
  url: string,
  { publicOrigin, denseVersion = 7, messages }: { publicOrigin?: string; denseVersion?: number; messages?: Partial<typeof QR_MESSAGES> } = {},
): QrIssue[] {
  const t = { ...QR_MESSAGES, ...messages }
  const issues: QrIssue[] = []
  const clean = url.replace(HIDDEN, "")
  if (clean !== url) issues.push({ id: "hidden", tone: "danger", message: t.hidden, fix: { label: t.hiddenFix, value: clean } })
  let parsed: URL | null = null
  try {
    parsed = new URL(clean)
  } catch {
    // Not a URL: the remaining checks still apply.
  }
  const swap = () =>
    parsed && publicOrigin
      ? { label: fill(t.publicFix, { host: new URL(publicOrigin).host }), value: new URL(parsed.pathname + parsed.search + parsed.hash, publicOrigin).toString() }
      : undefined
  if (parsed && LOCAL.test(parsed.hostname)) {
    issues.push({ id: "local", tone: "danger", message: fill(t.local, { host: parsed.host }), fix: swap() })
  } else if (parsed && STAGING.test(parsed.hostname.split(".").slice(0, -1).join("."))) {
    issues.push({ id: "staging", tone: "warning", message: fill(t.staging, { host: parsed.hostname }), fix: swap() })
  }
  if (parsed?.protocol === "http:" && !LOCAL.test(parsed.hostname)) {
    issues.push({ id: "http", tone: "warning", message: t.http, fix: { label: t.httpFix, value: clean.replace(/^http:/i, "https:") } })
  }
  const version = versionFor(clean)
  if (version === null) {
    issues.push({ id: "too-long", tone: "danger", message: t.tooLong })
  } else if (version >= denseVersion) {
    const stripped = withoutTracking(clean)
    const after = versionFor(stripped)
    const modules = (v: number) => `${v * 4 + 17}×${v * 4 + 17}`
    issues.push({
      id: "dense",
      tone: "warning",
      message: fill(t.dense, { modules: modules(version) }),
      fix: after && after < version ? { label: fill(t.denseFix, { modules: modules(after) }), value: stripped } : undefined,
    })
  }
  return issues
}

/** Shows the URL with the host in bold and every invisible character made visible. */
function Readback({ url }: { url: string }) {
  const match = url.match(/^([a-z][\w+.-]*:\/\/)([^/?#]*)(.*)$/is)
  const mark = (text: string) =>
    text.split(/([\s\u00a0\u200b-\u200f\u2028\u2029\u2060\ufeff])/).map((part, i) =>
      i % 2 ? (
        <mark key={i} title={`U+${part.charCodeAt(0).toString(16).toUpperCase().padStart(4, "0")}`} className="rounded-sm bg-red-500/20 px-0.5 text-red-700 dark:text-red-300">
          ␣
        </mark>
      ) : (
        part
      ),
    )
  if (!match) return <>{mark(url)}</>
  return (
    <>
      <span className="text-muted-foreground">{mark(match[1])}</span>
      <span className="font-semibold text-foreground">{mark(match[2])}</span>
      {mark(match[3])}
    </>
  )
}

const fixClass = {
  warning: "border-amber-500/40 text-amber-900 hover:bg-amber-500/10 dark:text-amber-200",
  danger: "border-red-500/40 text-red-900 hover:bg-red-500/10 dark:text-red-200",
}

export interface QrShareProps extends Omit<React.ComponentProps<"div">, "children" | "defaultValue"> {
  /** Controlled URL. */
  value?: string
  /** Initial URL when uncontrolled. */
  defaultValue?: string
  /** Called with the new URL when a one-tap fix is used. */
  onValueChange?: (value: string) => void
  /** The live origin (e.g. "https://acme.com") offered in place of localhost or staging. */
  publicOrigin?: string
  /** Rendered width of the code in px, quiet zone included. */
  size?: number
  /** Version from which a code counts as dense (7 = 45×45 dots). */
  denseVersion?: number
  /** Overrides for the issue messages in `QR_MESSAGES`. */
  messages?: Partial<typeof QR_MESSAGES>
  /** Templates: `{count}` (characters), `{modules}` and `{print}` are filled in. */
  verifiedText?: string
  mismatchText?: string
}

/**
 * Stops a QR code going out that opens the wrong thing. It reads the exact URL
 * back under the code, decodes the code it drew to prove nothing was cut off,
 * and warns when the link points at localhost or staging, uses http, hides
 * invisible characters, or is long enough to make a dense, slow-scanning code.
 */
export function QrShare({
  value,
  defaultValue = "",
  onValueChange,
  publicOrigin,
  size = 176,
  denseVersion = 7,
  messages,
  verifiedText = "Scans back as exactly these {count} characters · {modules} · print ≥ {print}",
  mismatchText = "This code doesn't scan back as the link above. Don't share it.",
  className,
  ...props
}: QrShareProps) {
  const [inner, setInner] = React.useState(defaultValue)
  const url = value ?? inner
  const svgRef = React.useRef<SVGSVGElement>(null)

  const code = React.useMemo<QrCode | null>(() => {
    try {
      return url ? encodeQr(url) : null
    } catch {
      return null
    }
  }, [url])
  const verified = code ? decodeQr(code.modules) === url : false
  const issues = checkQrUrl(url, { publicOrigin, denseVersion, messages })

  // A quick fade tells you the code itself changed after a fix.
  React.useEffect(() => {
    if (!svgRef.current || matchMedia("(prefers-reduced-motion: reduce)").matches) return
    svgRef.current.animate([{ opacity: 0.25, transform: "scale(0.97)" }, { opacity: 1, transform: "scale(1)" }], { duration: 250, easing: "ease-out" })
  }, [code])

  const update = (next: string) => {
    if (value === undefined) setInner(next)
    onValueChange?.(next)
  }

  const quiet = 4
  const total = code ? code.size + quiet * 2 : 0
  const path = code
    ? code.modules.flatMap((row, y) => row.map((dark, x) => (dark ? `M${x + quiet} ${y + quiet}h1v1h-1z` : ""))).join("")
    : ""
  const values = code
    ? {
        count: String([...url].length),
        modules: `${code.size}×${code.size}`,
        print: `${(((code.size + 8) * 0.4) / 10).toFixed(1)} cm`,
      }
    : null

  return (
    <div data-slot="qr-share" className={cn("grid w-full max-w-sm justify-items-center gap-3 text-sm", className)} {...props}>
      {code && (
        // Always dark on white: many scanners can't read an inverted code, so this ignores dark mode.
        <div className="rounded-lg border bg-white p-1 shadow-xs">
          <svg ref={svgRef} role="img" aria-label={`QR code for ${url}`} viewBox={`0 0 ${total} ${total}`} width={size} height={size} shapeRendering="crispEdges">
            <path d={path} fill="#000" />
          </svg>
        </div>
      )}
      <div className="grid w-full gap-1.5">
        <p className="rounded-md border bg-muted/40 px-3 py-2 font-mono text-xs leading-relaxed break-all">
          <Readback url={url} />
        </p>
        {code && values && (verified ? (
          <p className="flex items-start gap-1.5 text-xs text-muted-foreground">
            <CircleCheck aria-hidden className="mt-px size-3.5 shrink-0 text-emerald-600 dark:text-emerald-400" />
            <span>{fill(verifiedText, values)}</span>
          </p>
        ) : (
          <p role="alert" className="flex items-start gap-1.5 text-xs text-red-700 dark:text-red-400">
            <OctagonAlert aria-hidden className="mt-px size-3.5 shrink-0" />
            {mismatchText}
          </p>
        ))}
      </div>
      <ul aria-live="polite" className="grid w-full gap-1.5 text-xs empty:hidden">
        {issues.map((issue) => {
          const Icon = issue.tone === "danger" ? OctagonAlert : TriangleAlert
          return (
            <li key={issue.id} className={cn("flex gap-1.5", issue.tone === "danger" ? "text-red-700 dark:text-red-400" : "text-amber-700 dark:text-amber-400")}>
              <span className="flex h-6 shrink-0 items-center">
                <Icon aria-hidden className="size-3.5" />
              </span>
              <span className="flex min-w-0 flex-wrap items-center gap-x-2">
                <span className="py-1">{issue.message}</span>
                {issue.fix && (
                  <button
                    type="button"
                    onClick={() => issue.fix && update(issue.fix.value)}
                    className={cn("inline-flex h-6 items-center rounded-md border px-2 font-medium whitespace-nowrap transition-colors outline-none focus-visible:ring-[3px] focus-visible:ring-ring/50", fixClass[issue.tone])}
                  >
                    {issue.fix.label}
                  </button>
                )}
              </span>
            </li>
          )
        })}
      </ul>
    </div>
  )
}
